export function Keyframes({
  preset = "{{preset}}",
  duration = {{duration}},
  loop = {{loop}},
  accent = "{{accent}}",
}) {
  const names = { bounce: "mot-kf-bounce", "colour-cycle": "mot-kf-colour", "scale-pulse": "mot-kf-scale" };
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa" }}>
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8 }}>
        <span>0%</span><span>33%</span><span>66%</span><span>100%</span>
      </div>
      <div className={loop ? "box box--loop" : "box"} style={{ width: 36, height: 36, borderRadius: 8, margin: "0 auto", background: accent }} />
      <p style={{ margin: "10px 0 0", textAlign: "center" }}>@keyframes {preset} &middot; {duration}ms</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .box { animation: ${names[preset]} ${duration}ms ease-in-out 1; }
          .box--loop { animation-iteration-count: infinite; }
          @keyframes mot-kf-bounce { 0% { transform: translateY(0); } 33% { transform: translateY(-24px); } 66% { transform: translateY(0); } 100% { transform: translateY(0); } }
          @keyframes mot-kf-colour { 0% { background: #A8E6C1; } 33% { background: #F5C2E0; } 66% { background: #BFD9F2; } 100% { background: #A8E6C1; } }
          @keyframes mot-kf-scale { 0% { transform: scale(1); } 33% { transform: scale(1.5); } 66% { transform: scale(.8); } 100% { transform: scale(1); } }
        }
      `}</style>
    </div>
  );
}
